import { fetchJson, formatNumber } from './common.js';

const detailsGapPixels = 12;
const metersPerSecondToKilometersPerHour = 3.6;
const aiIcon =
	'<svg viewBox="0 0 24 24" role="img" aria-label="Generated by AI"><title>Generated by AI</title><path d="M10 2l2.5 7.5L20 12l-7.5 2.5L10 22l-2.5-7.5L0 12l7.5-2.5zM19 1l1 3 3 1-3 1-1 3-1-3-3-1 3-1z"/></svg>';

export function createDetails() {
	const details = document.getElementById('details');
	const groups = document.getElementById('groups');
	const summary = document.getElementById('summary');
	const header = document.getElementById('header');

	function update(aircraft) {
		const formatValue = (number, scale = 1) => (number == null ? null : formatNumber(Math.round(number * scale)));
		const rate = aircraft.verticalRate == null ? null : Math.round(aircraft.verticalRate);
		const arrow = rate > 0 ? '▲ ' : rate < 0 ? '▼ ' : '';
		const identity = document.createElement('div');
		const callsign = document.createElement('h2');
		callsign.textContent = aircraft.callsign ?? '-';
		const subtitle = document.createElement('p');
		subtitle.textContent = `${aircraft.icao24} · ${aircraft.category}`;
		identity.append(callsign, subtitle);
		const state = document.createElement('dl');
		for (const [label, text, unit] of [
			['Altitude', formatValue(aircraft.altitude), 'm'],
			['Speed', formatValue(aircraft.speed, metersPerSecondToKilometersPerHour), 'km/h'],
			['Heading', formatValue(aircraft.heading), '°'],
			['Vertical rate', rate == null ? null : arrow + Math.abs(rate), 'm/s'],
		]) {
			const term = document.createElement('dt');
			term.textContent = label;
			const description = document.createElement('dd');
			description.textContent = text ?? '-';
			if (text != null) {
				description.dataset.unit = unit;
			}
			const cell = document.createElement('div');
			cell.append(term, description);
			state.append(cell);
		}
		groups.replaceChildren(identity, state);
	}

	function showSummary(icao24, { isCurrent, onContentLoaded }) {
		summary.hidden = true;
		summary.replaceChildren();
		fetchJson(`/api/aircraft-summary?icao24=${encodeURIComponent(icao24)}`, 'Aircraft summary')
			.then((response) => response.summary)
			.catch((error) => {
				console.error(error);
				return 'Summary unavailable';
			})
			.then((text) => {
				if (text && isCurrent()) {
					summary.innerHTML = aiIcon;
					summary.append(text);
					summary.hidden = false;
					onContentLoaded();
				}
			});
	}

	function show(aircraft, callbacks) {
		update(aircraft);
		showSummary(aircraft.icao24, callbacks);
	}

	function place(box) {
		details.hidden = !box;
		if (!box) {
			return;
		}
		const { offsetWidth, offsetHeight } = details;
		const fitsRight = box.x + box.width + detailsGapPixels + offsetWidth <= innerWidth - detailsGapPixels;
		const x = fitsRight ? box.x + box.width + detailsGapPixels : box.x - detailsGapPixels - offsetWidth;
		const y = Math.min(Math.max(box.y, header.offsetHeight), innerHeight - detailsGapPixels - offsetHeight);
		details.style.transform = `translate(${x}px, ${y}px)`;
	}

	return { show, update, place };
}
